		SELECT ?geneEns {
			?geneB genex:isExpressedIn ?cond ;
				lscr:xrefEnsemblGene ?geneEns .
			?cond genex:hasDevelopmentalStage ?st .
			?cond genex:hasAnatomicalEntity ?anat .
			?st rdfs:label 'infant stage' .
			?anat rdfs:label 'brain' .
			?geneB orth:organism ?o .
			?o obo:RO_0002162 ?taxon2 .
			?taxon2 up:commonName 'human' .
		}
	}
	SERVICE <https://sparql.uniprot.org/sparql/> {
		?uniprot rdfs:seeAlso / up:transcribedFrom ?geneEns .
		?uniprot up:annotation ?annotation .
		?annotation a up:Disease_Annotation .
		?annotation rdfs:comment ?annotation_text .
	}
}

countQueries.query:
PREFIX owl: <http://www.w3.org/2002/07/owl#>
SELECT (COUNT(*) AS ?n) WHERE {
  ?swisslipid owl:equivalentClass ?chebi .
}

PREFIX rh: <http://rdf.rhea-db.org/>
SELECT ?rhea (COUNT(*) AS ?n) WHERE {
  ?rhea rh:side/rh:contains/rh:compound ?compound .
  ?compound (rh:chebi|(rh:reactivePart/rh:chebi)|(rh:underlyingChebi/rh:chebi)) ?metabolite .
} GROUP BY ?rhea

PREFIX up: <http://purl.uniprot.org/core/>
SELECT ?rhea (COUNT(*) AS ?n) WHERE {
  ?catalyticActivityAnnotation up:catalyticActivity/up:catalyzedReaction ?rhea .
  ?protein up:annotation ?catalyticActivityAnnotation ;
           up:organism ?organism .
} GROUP BY ?rhea

PREFIX SWISSLIPID: <https://swisslipids.org/rdf/SLM_>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT (COUNT(*) AS ?n) WHERE {
  ?swisslipid owl:equivalentClass ?chebi .
  ?swisslipidIsomericSubpecies rdfs:subClassOf ?swisslipid ;
        SWISSLIPID:rank SWISSLIPID:Isomeric_Subspecies .
}

PREFIX taxon: <http://purl.uniprot.org/taxonomy/>
PREFIX up: <http://purl.uniprot.org/core/>
SELECT ?rhea (COUNT(*) AS ?n) WHERE {
  ?catalyticActivityAnnotation up:catalyticActivity/up:catalyzedReaction ?rhea .
  ?protein up:annotation ?catalyticActivityAnnotation ;
           up:organism taxon:9606 .
} GROUP BY ?rhea
